{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text for accessibility and the field label.",
      "required": true
    },
    {
      "name": "value",
      "type": "Value",
      "description": "Current controlled value.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: Value) => void",
      "description": "Called when custom content commits a new value."
    },
    {
      "name": "changeAction",
      "type": "(value: Value) => void | Promise<void>",
      "description": "Async action after onChange. ComplexSelector exposes optimistic value and busy state while pending."
    },
    {
      "name": "children",
      "type": "(value: Value, onChange: (value: Value) => void, close: () => void, state: ComplexSelectorRenderState) => ReactNode",
      "description": "Custom dialog content. Receives positional value, onChange, close, and state helpers.",
      "required": true
    },
    {
      "name": "triggerLabel",
      "type": "ReactNode",
      "description": "Label/content shown in the closed trigger."
    },
    {
      "name": "placeholder",
      "type": "ReactNode",
      "description": "Placeholder shown when triggerLabel is omitted.",
      "default": "'Select...'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the selector."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Shows loading state on the trigger."
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Validation status."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment; detached when variant is secondary or ghost); detached floats below as a separate element with spacing; tooltip reveals the message in an info-tip button.",
      "default": "'attached' for input selectors; 'detached' for secondary and ghost selectors"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Exact trigger height: sm 28px, md 32px, or lg 36px.",
      "default": "'md'"
    },
    {
      "name": "variant",
      "type": "'input' | 'secondary' | 'ghost'",
      "description": "Visual trigger style. Input is the bordered form treatment; secondary matches the secondary buttons of the active theme (borderless and neutral-filled by default); ghost is borderless and transparent to match ghost buttons.",
      "default": "'input'"
    },
    {
      "name": "startIcon",
      "type": "ReactNode | IconType",
      "description": "Icon displayed at the start of the trigger."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field."
    },
    {
      "name": "placement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Popup placement.",
      "default": "'below'"
    },
    {
      "name": "alignment",
      "type": "'start' | 'center' | 'end'",
      "description": "Popup alignment along the placement axis.",
      "default": "'start'"
    },
    {
      "name": "renderTrigger",
      "type": "(props: ComplexSelectorRenderTriggerProps) => ReactNode",
      "description": "Render the control the popup hangs off — a glyph in a list row, a chip, an icon button — instead of the selector's own field and button. Spread the given props ({ref, id, onClick, onKeyDown, role, aria-haspopup, aria-expanded, aria-controls, aria-busy, aria-required, aria-disabled}) onto it: the control becomes the selector's combobox field, the popup is anchored to it and still labelled by `label`, and a disabled control keeps its tab stop but does not open. The field chrome is not rendered. Pair with handleRef to open from a keystroke elsewhere."
    },
    {
      "name": "handleRef",
      "type": "React.Ref<ComplexSelectorHandle>",
      "description": "Imperative handle for programmatic control. Exposes open(), close(), toggle(), and isOpen()."
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Called whenever the surface opens or closes, however it happened — trigger, keyboard, light dismiss, Escape, close(), or the imperative handle."
    },
    {
      "name": "contentXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the popup content container."
    },
    {
      "name": "onClick",
      "type": "(event: MouseEvent) => void",
      "description": "Click handler on the trigger. Runs before the popup opens; call preventDefault() to keep it closed. A press elsewhere in the control box goes through the trigger too. With renderTrigger it runs after the built-in toggle and cannot cancel it."
    },
    {
      "name": "onKeyDown",
      "type": "(event: KeyboardEvent) => void",
      "description": "Key handler on the trigger. Runs after the built-in handling and receives every key, including the ArrowDown that opens the popup. With renderTrigger it is skipped for keys the built-in handling cancels."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds the value, icons, and end controls. Never the trigger button itself."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
